/// <summary>
/// <c>METMarkupTransDS_Extension</c> class holds the COC of datasource MarkupTrans for form MarkupTrans
/// </summary>
/// Bug - 142610
[ExtensionOf(FormDataSourcestr(MarkupTrans, MarkupTrans))]
public final class METMarkupTransDS_Extension
{
}

Method.Source:
/// <summary>
/// COC of Active method
/// </summary>
/// <returns>int</returns>
int  active()
{
    int ret;

    ret = next active();

    MarkupTrans markupTransloc = this.cursor();

    if(markupTransloc.MarkupCode == '' || (markupTransloc.MarkupCode != '' && !markupTransloc.METAdvancedCalculation))
    {
        this.object(fieldNum(MarkupTrans, METChargesMethod)).enabled(false);
    }
    else
    {
        this.object(fieldNum(MarkupTrans, METChargesMethod)).enabled(true);
    }


    return ret;
}
